import { columnColors, columnColorsOpacity, neonColors } from "../constants/color";
import { ColumnProps } from "../types";
import CardItem from "./Card";
import {
  SortableContext,
  verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import { useDroppable } from "@dnd-kit/core";
import React from "react";
import { FaCirclePlus } from "react-icons/fa6";


function Column({ column, cards, index }: ColumnProps) {
  const color = columnColors[index];
   const lightColor = columnColorsOpacity[index];
  const { setNodeRef,isOver } = useDroppable({
  id: column.id,
});
  const getColorFromId = (id: string) => {
  const index = parseInt(id, 10) % neonColors.length;
  return neonColors[index];
};
  return (
    <div
    ref={setNodeRef}
      style={{
        flex: 1,
        height: "100%",
        padding: 10,
        borderWidth: 3,
        borderStyle: "solid",
        borderColor: color,
        borderRadius: 10,
        display: "flex",
        flexDirection: "column",
        backgroundColor: isOver ? lightColor : "transparent",
      }}
    >
      <div style={{flex: 1, flexDirection:'row', backgroundColor:'pink'}}>
      <span style={{ color: color, flex:3 }}>{column.title}</span>
        {column.title == 'Todo'&&<FaCirclePlus style={{flex:1}} color={color}/>}
</div>
      <SortableContext
        items={column.cardIds}
        strategy={verticalListSortingStrategy}
      >
        {column.cardIds.map((id) => (
          <CardItem  id={id} key={id} card={cards[id]} color={getColorFromId(id)}/>
        ))}
      </SortableContext>
    </div>
  );
}

export default React.memo(Column);
